-- Get column names properly
PRAGMA table_info(measurements);

-- Get all column names from sqlite_master
SELECT name FROM sqlite_master WHERE type='table' AND name='measurements';

-- Check if table exists
SELECT name FROM sqlite_master WHERE type='table';

-- List the schema
SELECT sql FROM sqlite_master WHERE type='table';

-- Verify the cleaned_measurements table was created correctly
SELECT COUNT(*) as count FROM cleaned_measurements;

-- Show some sample data
SELECT * FROM cleaned_measurements 
ORDER BY recorded_at DESC
LIMIT 5;

-- Compare statistics
SELECT COUNT(*) as original_count FROM measurements;
